import{_ as l,a0 as t,w as o,s as d,ao as r,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何對你的 Linux 系統進行壓力測試 | LCTT x X-CMD","titleTemplate":false,"description":"如何對你的 Linux 系統進行壓力測試 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何對你的 Linux 系統進行壓力測試 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何對你的 Linux 系統進行壓力測試 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200625 How to stress test your Linux system","title":"如何對你的 Linux 系統進行壓力測試","tag":"202007","desc":""},"relativePath":"202007/20200625 How to stress test your Linux system.md","filePath":"[post].md"}'),c={name:"202007/20200625 How to stress test your Linux system.md"};function h(u,s,g,k,b,y){const n=t("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何對你的-linux-系統進行壓力測試" tabindex="-1">如何對你的 Linux 系統進行壓力測試 <a class="header-anchor" href="#如何對你的-linux-系統進行壓力測試" aria-label="Permalink to “如何對你的 Linux 系統進行壓力測試”">​</a></h1><blockquote><p>如果你想了解 Linux 服務器在重壓之下的運行情況，那麼給 Linux 服務器施加壓力是個不錯的主意。在這篇文章中，我們將看一些工具，可以幫助你增加服務器壓力並衡量結果。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2020/06/stress-test2_linux-penguin-stress-ball_hand-squeezing_by-digitalsoul-getty-images_1136841639-100850120-large.jpg" alt=""></p><p>為什麼你會想給你的 Linux 系統施加壓力呢？因為有時你可能想知道當一個系統由於大量運行的進程、繁重的網絡流量、過多的內存使用等原因而承受很大的壓力時，它的表現如何。這種壓力測試可以幫助確保系統已經做好了 “上市” 的準備。</p><p>如果你需要預測應用程序可能需要多長時間才能做出反應，以及哪些（如果有的話）進程可能會在重負載下失敗或運行緩慢，那麼在前期進行壓力測試是一個非常好的主意。</p><p>幸運的是，對於那些需要能夠預測 Linux 系統在壓力下的反應的人來説，你可以採用一些有用的技術和工具來使這個過程更容易。在這篇文章中，我們將研究其中的一些。</p><h3 id="自己動手做個循環" tabindex="-1">自己動手做個循環 <a class="header-anchor" href="#自己動手做個循環" aria-label="Permalink to “自己動手做個循環”">​</a></h3><p>第一種技術是在命令列上運行一些循環，觀察它們對系統的影響。這種方式可以大大增加 CPU 的負荷。使用 <code>uptime</code> 或類似的命令可以很容易地看到結果。</p><p>在下面的命令中，我們啓動了四個無盡循環。你可以通過添加數字或使用 bash 表達式，如 <code>{1...6}</code> 來代替 <code>1 2 3 4</code> 以增加循環次數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in 1 2 3 4; do while : ; do : ; done &amp; done</span></span></code></pre></div><p>在命令列上輸入後，將在後台啓動四個無盡循環：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for i in 1 2 3 4; do while : ; do : ; done &amp; done</span></span>
<span class="line"><span>[1] 205012</span></span>
<span class="line"><span>[2] 205013</span></span>
<span class="line"><span>[3] 205014</span></span>
<span class="line"><span>[4] 205015</span></span></code></pre></div><p>在這種情況下，發起了作業 1-4，作業號和進程號會相應顯示出來。</p><p>要觀察對平均負載的影響，請使用如下所示的命令。在本例中，<code>uptime</code> 命令每 30 秒運行一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ while true; do uptime; sleep 30; done</span></span></code></pre></div><p>如果你打算定期運行這樣的測試，你可以將循環命令放入腳本 <code>watch-it</code> 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while true</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  uptime</span></span>
<span class="line"><span>  sleep 30</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>在輸出中，你可以看到平均負載是如何增加的，然後在循環結束後又開始下降。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> 11:25:34 up 5 days, 17:27,  2 users,  load average: 0.15, 0.14, 0.08</span></span>
<span class="line"><span> 11:26:04 up 5 days, 17:27,  2 users,  load average: 0.09, 0.12, 0.08</span></span>
<span class="line"><span> 11:26:34 up 5 days, 17:28,  2 users,  load average: 1.42, 0.43, 0.18</span></span>
<span class="line"><span> 11:27:04 up 5 days, 17:28,  2 users,  load average: 2.50, 0.79, 0.31</span></span>
<span class="line"><span> 11:27:34 up 5 days, 17:29,  2 users,  load average: 3.09, 1.10, 0.43</span></span>
<span class="line"><span> 11:28:04 up 5 days, 17:29,  2 users,  load average: 3.45, 1.38, 0.54</span></span>
<span class="line"><span> 11:28:34 up 5 days, 17:30,  2 users,  load average: 3.67, 1.63, 0.66</span></span>
<span class="line"><span> 11:29:04 up 5 days, 17:30,  2 users,  load average: 3.80, 1.86, 0.76</span></span>
<span class="line"><span> 11:29:34 up 5 days, 17:31,  2 users,  load average: 3.88, 2.06, 0.87</span></span>
<span class="line"><span> 11:30:04 up 5 days, 17:31,  2 users,  load average: 3.93, 2.25, 0.97</span></span>
<span class="line"><span> 11:30:34 up 5 days, 17:32,  2 users,  load average: 3.64, 2.35, 1.04 &lt;== 循環停止</span></span>
<span class="line"><span> 11:31:04 up 5 days, 17:32,  2 users,  load average: 2.20, 2.13, 1.01      11:31:34 up 5 days, 17:33,  2 users,  load average: 1.40, 1.94, 0.98</span></span></code></pre></div><p>因為所顯示的負載分別代表了 1、5 和 15 分鐘的平均值，所以這些值需要一段時間才能恢復到系統接近正常的狀態。</p><p>要停止循環，請發出像下面這樣的 <code>kill</code> 命令 —— 假設作業號是 1-4，就像本篇文章前面顯示的那樣。如果你不確定，可以使用 <code>jobs</code> 命令來確認作業號。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kill %1 %2 %3 %4</span></span></code></pre></div><h3 id="增加壓力的專用工具" tabindex="-1">增加壓力的專用工具 <a class="header-anchor" href="#增加壓力的專用工具" aria-label="Permalink to “增加壓力的專用工具”">​</a></h3><p>另一種方法是使用專門為你製造系統壓力的工具。其中一種叫做 <code>stress</code>（壓力），可以以多種方式對系統進行壓力測試。<code>stress</code> 工具是一個工作負載生成器，提供 CPU、內存和磁盤 I/O 壓力測試。</p><p>在使用 <code>--cpu</code> 選項時，<code>stress</code> 命令使用平方根函數強制 CPU 努力工作。指定的 CPU 數量越多，負載上升的速度就越快。</p><p>下面第二個腳本（<code>watch-it-2</code>）可以用來衡量對系統內存使用的影響。請注意，它使用 <code>free</code> 命令來查看加壓的效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat watch-it-2</span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while true</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  free</span></span>
<span class="line"><span>  sleep 30</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>發起任務並觀察壓力：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stress --cpu 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ./watch-it</span></span>
<span class="line"><span> 13:09:14 up 5 days, 19:10,  2 users,  load average: 0.00, 0.00, 0.00</span></span>
<span class="line"><span> 13:09:44 up 5 days, 19:11,  2 users,  load average: 0.68, 0.16, 0.05</span></span>
<span class="line"><span> 13:10:14 up 5 days, 19:11,  2 users,  load average: 1.20, 0.34, 0.12</span></span>
<span class="line"><span> 13:10:44 up 5 days, 19:12,  2 users,  load average: 1.52, 0.50, 0.18</span></span>
<span class="line"><span> 13:11:14 up 5 days, 19:12,  2 users,  load average: 1.71, 0.64, 0.24</span></span>
<span class="line"><span> 13:11:44 up 5 days, 19:13,  2 users,  load average: 1.83, 0.77, 0.30</span></span></code></pre></div><p>在命令列中指定的 CPU 越多，負載就增加的越快。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stress --cpu 4</span></span>
<span class="line"><span>$ ./watch-it</span></span>
<span class="line"><span> 13:47:49 up 5 days, 19:49,  2 users,  load average: 0.00, 0.00, 0.00</span></span>
<span class="line"><span> 13:48:19 up 5 days, 19:49,  2 users,  load average: 1.58, 0.38, 0.13</span></span>
<span class="line"><span> 13:48:49 up 5 days, 19:50,  2 users,  load average: 2.61, 0.75, 0.26</span></span>
<span class="line"><span> 13:49:19 up 5 days, 19:50,  2 users,  load average: 3.16, 1.06, 0.38</span></span>
<span class="line"><span> 13:49:49 up 5 days, 19:51,  2 users,  load average: 3.49, 1.34, 0.50</span></span>
<span class="line"><span> 13:50:19 up 5 days, 19:51,  2 users,  load average: 3.69, 1.60, 0.61</span></span></code></pre></div><p><code>stress</code> 命令也可以通過 <code>--io</code>（輸入/輸出）和 <code>--vm</code>（內存）選項增加 I/O 和內存的負載來給系統施加壓力。</p><p>在接下來的這個例子中，運行這個增加內存壓力的命令，然後啓動 <code>watch-it-2</code> 腳本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stress --vm 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ watch-it-2</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6087064      662160     2519164        8868     2905740     5117548</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6087064      803464     2377832        8864     2905768     4976248</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        6087064      968512     2212772        8864     2905780     4811200</span></span>
<span class="line"><span>Swap:       2097148           0     2097148</span></span></code></pre></div><p><code>stress</code> 的另一個選項是使用 <code>--io</code> 選項為系統添加輸入/輸出活動。在這種情況下，你可以使用這樣的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stress --io 4</span></span></code></pre></div><p>然後你可以使用 <code>iotop</code> 觀察受壓的 I/O。注意，運行 <code>iotop</code> 需要 root 權限。</p><p>之前：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iotop -o</span></span>
<span class="line"><span>Total DISK READ:         0.00 B/s | Total DISK WRITE:        19.36 K/s</span></span>
<span class="line"><span>Current DISK READ:       0.00 B/s | Current DISK WRITE:      27.10 K/s</span></span>
<span class="line"><span>    TID  PRIO  USER     DISK READ  DISK WRITE  SWAPIN     IO&gt;    COMMAND</span></span>
<span class="line"><span> 269308 be/4 root        0.00 B/s    0.00 B/s  0.00 %  1.24 % [kworker~fficient]</span></span>
<span class="line"><span>    283 be/3 root        0.00 B/s   19.36 K/s  0.00 %  0.26 % [jbd2/sda1-8]</span></span></code></pre></div><p>之後：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Total DISK READ:         0.00 B/s | Total DISK WRITE:         0.00 B/s</span></span>
<span class="line"><span>Current DISK READ:       0.00 B/s | Current DISK WRITE:       0.00 B/s</span></span>
<span class="line"><span>    TID  PRIO  USER     DISK READ  DISK WRITE  SWAPIN     IO&gt;    COMMAND</span></span>
<span class="line"><span> 270983 be/4 shs         0.00 B/s    0.00 B/s  0.00 % 51.45 % stress --io 4</span></span>
<span class="line"><span> 270984 be/4 shs         0.00 B/s    0.00 B/s  0.00 % 51.36 % stress --io 4</span></span>
<span class="line"><span> 270985 be/4 shs         0.00 B/s    0.00 B/s  0.00 % 50.95 % stress --io 4</span></span>
<span class="line"><span> 270982 be/4 shs         0.00 B/s    0.00 B/s  0.00 % 50.80 % stress --io 4</span></span>
<span class="line"><span> 269308 be/4 root        0.00 B/s    0.00 B/s  0.00 %  0.09 % [kworker~fficient]</span></span></code></pre></div><p><code>stress</code> 只是給系統增加壓力的若干工具之一。另一個較新的工具，<code>stress-ng</code>，將在以後的文章中介紹。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>用於系統壓力測試的各種工具可以幫助你預測系統在真實世界的情況下如何響應，在這些情況下，它們受到增加的流量和計算需求。</p><p>雖然我們在文章中展示的是創建和測量各種類型的壓力的方法，但最終的好處是壓力如何幫助確定你的系統或應用程序對它的反應。</p><hr>`,46)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3563334/how-to-stress-test-your-linux-system.html"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3563334/how-to-stress-test-your-linux-system.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=l(c,[["render",h]]);export{v as __pageData,C as default};
